#include "tbox_ua_style.h"

#include <stdio.h>
#include <string.h>

#include "css_parser/tbox_css_stylesheet.h"

/* These types describe declarations before they enter the text-valued CSS
 * cascade. A declaration list keeps source order and supports repeated
 * properties; no "has_property" flags or fixed-size CSS buffers are needed. */
typedef enum tbox_ua_unit {
    TBOX_UA_UNIT_PX,
    TBOX_UA_UNIT_EM,
    TBOX_UA_UNIT_PERCENT,
    TBOX_UA_UNIT_AUTO,
} tbox_ua_unit;

typedef struct tbox_ua_length {
    double value;
    tbox_ua_unit unit;
} tbox_ua_length;

typedef struct tbox_ua_quad {
    tbox_ua_length top, right, bottom, left;
} tbox_ua_quad;

typedef struct tbox_ua_color {
    unsigned char r, g, b, a;
} tbox_ua_color;

typedef enum tbox_ua_border_style {
    TBOX_UA_BORDER_SOLID,
} tbox_ua_border_style;

typedef struct tbox_ua_border {
    tbox_ua_length width;
    tbox_ua_border_style style;
    tbox_ua_color color;
} tbox_ua_border;

typedef enum tbox_ua_keyword {
    TBOX_UA_KW_BLOCK,
    TBOX_UA_KW_INLINE,
    TBOX_UA_KW_INLINE_BLOCK,
    TBOX_UA_KW_NONE,
    TBOX_UA_KW_BOLD,
    TBOX_UA_KW_DISC,
    TBOX_UA_KW_DECIMAL,
    TBOX_UA_KW_ITALIC,
    TBOX_UA_KW_PRE,
    TBOX_UA_KW_MONOSPACE,
    TBOX_UA_KW_UNDERLINE,
    TBOX_UA_KW_LINE_THROUGH,
    TBOX_UA_KW_SUB,
    TBOX_UA_KW_SUPER,
    TBOX_UA_KW_CENTER,
} tbox_ua_keyword;

typedef enum tbox_ua_property {
    TBOX_UA_PROP_DISPLAY,
    TBOX_UA_PROP_MARGIN,
    TBOX_UA_PROP_FONT_SIZE,
    TBOX_UA_PROP_FONT_WEIGHT,
    TBOX_UA_PROP_PADDING,
    TBOX_UA_PROP_LIST_STYLE_TYPE,
    TBOX_UA_PROP_BORDER,
    TBOX_UA_PROP_WIDTH,
    TBOX_UA_PROP_HEIGHT,
    TBOX_UA_PROP_BACKGROUND_COLOR,
    TBOX_UA_PROP_BORDER_RADIUS,
    TBOX_UA_PROP_FONT_FAMILY,
    TBOX_UA_PROP_WHITE_SPACE,
    TBOX_UA_PROP_FONT_STYLE,
    TBOX_UA_PROP_COLOR,
    TBOX_UA_PROP_TEXT_DECORATION,
    TBOX_UA_PROP_VERTICAL_ALIGN,
    TBOX_UA_PROP_TEXT_ALIGN,
} tbox_ua_property;

typedef enum tbox_ua_value_kind {
    TBOX_UA_VALUE_KEYWORD,
    TBOX_UA_VALUE_LENGTH,
    TBOX_UA_VALUE_QUAD,
    TBOX_UA_VALUE_BORDER,
    TBOX_UA_VALUE_COLOR,
} tbox_ua_value_kind;

typedef struct tbox_ua_declaration {
    tbox_ua_property property;
    tbox_ua_value_kind kind;
    union {
        tbox_ua_keyword keyword;
        tbox_ua_length length;
        tbox_ua_quad quad;
        tbox_ua_border border;
        tbox_ua_color color;
    } value;
} tbox_ua_declaration;

typedef enum tbox_ua_qualifier {
    TBOX_UA_QUALIFIER_NONE,
    TBOX_UA_QUALIFIER_FOCUS,
    TBOX_UA_QUALIFIER_INPUT_TYPE,
} tbox_ua_qualifier;

typedef struct tbox_ua_selector {
    const char *tag;
    tbox_ua_qualifier qualifier;
    const char *input_type; /* only for INPUT_TYPE */
} tbox_ua_selector;

typedef struct tbox_ua_rule {
    const tbox_ua_selector *selectors;
    size_t selector_count;
    const tbox_ua_declaration *declarations;
    size_t declaration_count;
} tbox_ua_rule;

static const char *tbox_ua_property_name(tbox_ua_property property) {
    switch (property) {
    case TBOX_UA_PROP_DISPLAY:
        return "display";
    case TBOX_UA_PROP_MARGIN:
        return "margin";
    case TBOX_UA_PROP_FONT_SIZE:
        return "font-size";
    case TBOX_UA_PROP_FONT_WEIGHT:
        return "font-weight";
    case TBOX_UA_PROP_PADDING:
        return "padding";
    case TBOX_UA_PROP_LIST_STYLE_TYPE:
        return "list-style-type";
    case TBOX_UA_PROP_BORDER:
        return "border";
    case TBOX_UA_PROP_WIDTH:
        return "width";
    case TBOX_UA_PROP_HEIGHT:
        return "height";
    case TBOX_UA_PROP_BACKGROUND_COLOR:
        return "background-color";
    case TBOX_UA_PROP_BORDER_RADIUS:
        return "border-radius";
    case TBOX_UA_PROP_FONT_FAMILY:
        return "font-family";
    case TBOX_UA_PROP_WHITE_SPACE:
        return "white-space";
    case TBOX_UA_PROP_FONT_STYLE:
        return "font-style";
    case TBOX_UA_PROP_COLOR:
        return "color";
    case TBOX_UA_PROP_TEXT_DECORATION:
        return "text-decoration";
    case TBOX_UA_PROP_VERTICAL_ALIGN:
        return "vertical-align";
    case TBOX_UA_PROP_TEXT_ALIGN:
        return "text-align";
    }
    return NULL;
}

static const char *tbox_ua_keyword_name(tbox_ua_keyword keyword) {
    switch (keyword) {
    case TBOX_UA_KW_BLOCK:
        return "block";
    case TBOX_UA_KW_INLINE:
        return "inline";
    case TBOX_UA_KW_INLINE_BLOCK:
        return "inline-block";
    case TBOX_UA_KW_NONE:
        return "none";
    case TBOX_UA_KW_BOLD:
        return "bold";
    case TBOX_UA_KW_DISC:
        return "disc";
    case TBOX_UA_KW_DECIMAL:
        return "decimal";
    case TBOX_UA_KW_ITALIC:
        return "italic";
    case TBOX_UA_KW_PRE:
        return "pre";
    case TBOX_UA_KW_MONOSPACE:
        return "monospace";
    case TBOX_UA_KW_UNDERLINE:
        return "underline";
    case TBOX_UA_KW_LINE_THROUGH:
        return "line-through";
    case TBOX_UA_KW_SUB:
        return "sub";
    case TBOX_UA_KW_SUPER:
        return "super";
    case TBOX_UA_KW_CENTER:
        return "center";
    }
    return NULL;
}

static tbox_ua_value_kind tbox_ua_expected_kind(tbox_ua_property property) {
    switch (property) {
    case TBOX_UA_PROP_MARGIN:
    case TBOX_UA_PROP_PADDING:
        return TBOX_UA_VALUE_QUAD;
    case TBOX_UA_PROP_FONT_SIZE:
    case TBOX_UA_PROP_WIDTH:
    case TBOX_UA_PROP_HEIGHT:
    case TBOX_UA_PROP_BORDER_RADIUS:
        return TBOX_UA_VALUE_LENGTH;
    case TBOX_UA_PROP_BORDER:
        return TBOX_UA_VALUE_BORDER;
    case TBOX_UA_PROP_COLOR:
    case TBOX_UA_PROP_BACKGROUND_COLOR:
        return TBOX_UA_VALUE_COLOR;
    default:
        return TBOX_UA_VALUE_KEYWORD;
    }
}

static bool tbox_ua_keyword_matches_property(tbox_ua_property property, tbox_ua_keyword keyword) {
    switch (property) {
    case TBOX_UA_PROP_DISPLAY:
        return keyword == TBOX_UA_KW_BLOCK || keyword == TBOX_UA_KW_INLINE || keyword == TBOX_UA_KW_INLINE_BLOCK || keyword == TBOX_UA_KW_NONE;
    case TBOX_UA_PROP_FONT_WEIGHT:
        return keyword == TBOX_UA_KW_BOLD;
    case TBOX_UA_PROP_LIST_STYLE_TYPE:
        return keyword == TBOX_UA_KW_DISC || keyword == TBOX_UA_KW_DECIMAL;
    case TBOX_UA_PROP_FONT_FAMILY:
        return keyword == TBOX_UA_KW_MONOSPACE;
    case TBOX_UA_PROP_WHITE_SPACE:
        return keyword == TBOX_UA_KW_PRE;
    case TBOX_UA_PROP_FONT_STYLE:
        return keyword == TBOX_UA_KW_ITALIC;
    case TBOX_UA_PROP_TEXT_DECORATION:
        return keyword == TBOX_UA_KW_UNDERLINE || keyword == TBOX_UA_KW_LINE_THROUGH;
    case TBOX_UA_PROP_VERTICAL_ALIGN:
        return keyword == TBOX_UA_KW_SUB || keyword == TBOX_UA_KW_SUPER;
    case TBOX_UA_PROP_TEXT_ALIGN:
        return keyword == TBOX_UA_KW_CENTER;
    default:
        return false;
    }
}

static bool tbox_ua_format_length(tbox_ua_length length, char *buffer, size_t capacity) {
    const char *suffix = NULL;
    switch (length.unit) {
    case TBOX_UA_UNIT_PX:
        suffix = "px";
        break;
    case TBOX_UA_UNIT_EM:
        suffix = "em";
        break;
    case TBOX_UA_UNIT_PERCENT:
        suffix = "%";
        break;
    case TBOX_UA_UNIT_AUTO: {
        int written = snprintf(buffer, capacity, "auto");
        return written >= 0 && (size_t)written < capacity;
    }
    }
    if (suffix == NULL)
        return false;
    int written = snprintf(buffer, capacity, "%g%s", length.value, suffix);
    return written >= 0 && (size_t)written < capacity;
}

static bool tbox_ua_format_color(tbox_ua_color color, char *buffer, size_t capacity) {
    int written = color.a == 255 ? snprintf(buffer, capacity, "#%02x%02x%02x", color.r, color.g, color.b) : snprintf(buffer, capacity, "rgba(%u,%u,%u,%.17g)", color.r, color.g, color.b, (double)color.a / 255.0);
    return written >= 0 && (size_t)written < capacity;
}

static bool tbox_ua_format_value(const tbox_ua_declaration *declaration, char *buffer, size_t capacity) {
    if (declaration->kind != tbox_ua_expected_kind(declaration->property))
        return false;
    int written;
    switch (declaration->kind) {
    case TBOX_UA_VALUE_KEYWORD: {
        if (!tbox_ua_keyword_matches_property(declaration->property, declaration->value.keyword))
            return false;
        const char *name = tbox_ua_keyword_name(declaration->value.keyword);
        if (name == NULL)
            return false;
        written = snprintf(buffer, capacity, "%s", name);
        break;
    }
    case TBOX_UA_VALUE_LENGTH:
        return tbox_ua_format_length(declaration->value.length, buffer, capacity);
    case TBOX_UA_VALUE_QUAD: {
        char top[48], right[48], bottom[48], left[48];
        tbox_ua_quad quad = declaration->value.quad;
        if (!tbox_ua_format_length(quad.top, top, sizeof(top)) || !tbox_ua_format_length(quad.right, right, sizeof(right)) || !tbox_ua_format_length(quad.bottom, bottom, sizeof(bottom)) || !tbox_ua_format_length(quad.left, left, sizeof(left)))
            return false;
        written = snprintf(buffer, capacity, "%s %s %s %s", top, right, bottom, left);
        break;
    }
    case TBOX_UA_VALUE_BORDER: {
        char width[48], color[48];
        tbox_ua_border border = declaration->value.border;
        if (border.style != TBOX_UA_BORDER_SOLID || !tbox_ua_format_length(border.width, width, sizeof(width)) || !tbox_ua_format_color(border.color, color, sizeof(color)))
            return false;
        written = snprintf(buffer, capacity, "%s solid %s", width, color);
        break;
    }
    case TBOX_UA_VALUE_COLOR:
        return tbox_ua_format_color(declaration->value.color, buffer, capacity);
    default:
        return false;
    }
    return written >= 0 && (size_t)written < capacity;
}

static bool tbox_ua_copy_string(tbox_arena *arena, const char *source, tbox_string_view *out) {
    size_t length = strlen(source);
    char *copy    = tbox_arena_alloc(arena, length + 1);
    if (copy == NULL)
        return false;
    memcpy(copy, source, length + 1);
    *out = tbox_string_view_make(copy, length);
    return true;
}

static bool tbox_ua_build_selector(tbox_arena *arena, const tbox_ua_selector *definition, tbox_css_selector *selector) {
    size_t part_count          = definition->qualifier == TBOX_UA_QUALIFIER_NONE ? 1 : 2;
    selector->simple_selectors = tbox_arena_alloc_zero(arena, part_count * sizeof(tbox_css_simple_selector));
    if (selector->simple_selectors == NULL)
        return false;
    selector->simple_selector_count = part_count;

    tbox_css_simple_selector *tag = &selector->simple_selectors[0];
    tag->kind                     = TBOX_CSS_SIMPLE_SELECTOR_TYPE;
    tag->combinator_before        = TBOX_CSS_COMBINATOR_NONE;
    if (!tbox_ua_copy_string(arena, definition->tag, &tag->name))
        return false;

    if (part_count == 1)
        return true;
    tbox_css_simple_selector *qualifier = &selector->simple_selectors[1];
    qualifier->combinator_before        = TBOX_CSS_COMBINATOR_NONE;
    if (definition->qualifier == TBOX_UA_QUALIFIER_FOCUS) {
        qualifier->kind = TBOX_CSS_SIMPLE_SELECTOR_PSEUDO;
        return tbox_ua_copy_string(arena, "focus", &qualifier->name);
    }
    if (definition->qualifier == TBOX_UA_QUALIFIER_INPUT_TYPE && definition->input_type != NULL) {
        qualifier->kind               = TBOX_CSS_SIMPLE_SELECTOR_ATTRIBUTE;
        qualifier->attribute_operator = TBOX_CSS_ATTR_EQUALS;
        return tbox_ua_copy_string(arena, "type", &qualifier->name) && tbox_ua_copy_string(arena, definition->input_type, &qualifier->attribute_value);
    }
    return false;
}

static tbox_css_stylesheet *tbox_ua_build_stylesheet(const tbox_ua_rule *rules, size_t rule_count) {
    tbox_css_stylesheet *stylesheet = tbox_css_stylesheet_create_empty();
    if (stylesheet == NULL)
        return NULL;
    tbox_arena *arena    = &stylesheet->arena;
    stylesheet->rulesets = tbox_arena_alloc_zero(arena, rule_count * sizeof(tbox_css_ruleset));
    if (stylesheet->rulesets == NULL)
        goto fail;
    stylesheet->ruleset_count = rule_count;

    for (size_t r = 0; r < rule_count; ++r) {
        const tbox_ua_rule *definition = &rules[r];
        tbox_css_ruleset *ruleset      = &stylesheet->rulesets[r];
        ruleset->selector_count        = definition->selector_count;
        ruleset->selectors             = tbox_arena_alloc_zero(arena, ruleset->selector_count * sizeof(tbox_css_selector));
        ruleset->declaration_count     = definition->declaration_count;
        ruleset->declarations          = tbox_arena_alloc_zero(arena, ruleset->declaration_count * sizeof(tbox_css_declaration));
        if (ruleset->selectors == NULL || ruleset->declarations == NULL)
            goto fail;

        for (size_t s = 0; s < ruleset->selector_count; ++s) {
            if (!tbox_ua_build_selector(arena, &definition->selectors[s], &ruleset->selectors[s]))
                goto fail;
        }
        for (size_t d = 0; d < ruleset->declaration_count; ++d) {
            const tbox_ua_declaration *source = &definition->declarations[d];
            tbox_css_declaration *target      = &ruleset->declarations[d];
            const char *property              = tbox_ua_property_name(source->property);
            char value[256];
            if (property == NULL || !tbox_ua_format_value(source, value, sizeof(value)) || !tbox_ua_copy_string(arena, property, &target->property) || !tbox_ua_copy_string(arena, value, &target->value))
                goto fail;
        }
    }
    return stylesheet;

fail:
    tbox_css_stylesheet_destroy(stylesheet);
    return NULL;
}

tbox_ua_style_config tbox_ua_style_config_default(void) {
    tbox_ua_style_config config;
    config.font.base_px         = 16.0;
    config.font.heading_em[0]   = 2.0;
    config.font.heading_em[1]   = 1.5;
    config.font.heading_em[2]   = 1.17;
    config.font.heading_em[3]   = 1.0;
    config.font.heading_em[4]   = 0.83;
    config.font.heading_em[5]   = 0.67;
    config.margin.heading_px[0] = 21.0;
    config.margin.heading_px[1] = 19.0;
    config.margin.heading_px[2] = 18.0;
    config.margin.heading_px[3] = 21.0;
    config.margin.heading_px[4] = 22.0;
    config.margin.heading_px[5] = 25.0;
    config.margin.paragraph_px  = 16.0;
    config.margin.body_px       = 8.0;
    config.margin.list_px       = 16.0;
    config.margin.hr_px         = 8.0;
    config.list_padding_left_px = 40.0;
    config.hr_height_px         = 2.0;
    return config;
}

/* Compact initializers keep the fixed UA rules readable. Numeric values are
 * still real typed lengths, not preformatted CSS fragments. */
#define UA_KW(property, kw)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    \
    {                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          \
        (property), TBOX_UA_VALUE_KEYWORD, {                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   \
            .keyword = (kw)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    \
        }                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      \
    }
#define UA_LEN(property, amount, unit)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         \
    {                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          \
        (property), TBOX_UA_VALUE_LENGTH, {                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    \
            .length = {(amount), (unit) }                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      \
        }                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      \
    }
#define UA_QUAD(property, top, right, bottom, left)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            \
    {                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          \
        (property), TBOX_UA_VALUE_QUAD, {                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      \
            .quad = {                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          \
                { (top),    TBOX_UA_UNIT_PX },                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    \
                { (right),  TBOX_UA_UNIT_PX },                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  \
                { (bottom), TBOX_UA_UNIT_PX },                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 \
                { (left),   TBOX_UA_UNIT_PX }                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    \
            }                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  \
        }                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      \
    }
#define UA_COLOR(property, red, green, blue)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   \
    {                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          \
        (property), TBOX_UA_VALUE_COLOR, {                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     \
            .color = { (red), (green), (blue), 255 }                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           \
        }                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      \
    }
#define UA_BORDER(width, red, green, blue)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     \
    {                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          \
        TBOX_UA_PROP_BORDER, TBOX_UA_VALUE_BORDER, {                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           \
            .border = {                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        \
                { (width), TBOX_UA_UNIT_PX },                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  \
                TBOX_UA_BORDER_SOLID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          \
                { (red), (green), (blue), 255 }                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                \
            }                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  \
        }                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      \
    }

#define UA_DECLARATIONS(...)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   \
    (const tbox_ua_declaration[]) {                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            \
        __VA_ARGS__                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            \
    }
#define UA_DECLARATION_COUNT(...) (sizeof(UA_DECLARATIONS(__VA_ARGS__)) / sizeof(tbox_ua_declaration))
#define UA_RULE_1(tag, ...) { (const tbox_ua_selector[]){ { (tag), TBOX_UA_QUALIFIER_NONE, NULL } }, 1, UA_DECLARATIONS(__VA_ARGS__), UA_DECLARATION_COUNT(__VA_ARGS__) }
#define UA_RULE_2(tag_a, tag_b, ...)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           \
    {                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          \
        (const tbox_ua_selector[]){ { (tag_a), TBOX_UA_QUALIFIER_NONE, NULL }, { (tag_b), TBOX_UA_QUALIFIER_NONE, NULL } }, \
         2, UA_DECLARATIONS(__VA_ARGS__), UA_DECLARATION_COUNT(__VA_ARGS__)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 \
            }
#define UA_RULE_6(a, b, c, d, e, f, ...)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       \
    {                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          \
        (const tbox_ua_selector[]){ { (a), TBOX_UA_QUALIFIER_NONE, NULL }, { (b), TBOX_UA_QUALIFIER_NONE, NULL }, { (c), TBOX_UA_QUALIFIER_NONE, NULL }, { (d), TBOX_UA_QUALIFIER_NONE, NULL }, { (e), TBOX_UA_QUALIFIER_NONE, NULL }, { (f), TBOX_UA_QUALIFIER_NONE, NULL } }, \
         6, UA_DECLARATIONS(__VA_ARGS__), UA_DECLARATION_COUNT(__VA_ARGS__)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             \
    }
#define UA_RULE_FOCUS(tag, ...) { (const tbox_ua_selector[]){ { (tag), TBOX_UA_QUALIFIER_FOCUS, NULL } }, 1, UA_DECLARATIONS(__VA_ARGS__), UA_DECLARATION_COUNT(__VA_ARGS__) }
#define UA_RULE_INPUT_TYPE(input_type, ...) { (const tbox_ua_selector[]){ { "input", TBOX_UA_QUALIFIER_INPUT_TYPE, (input_type) } }, 1, UA_DECLARATIONS(__VA_ARGS__), UA_DECLARATION_COUNT(__VA_ARGS__) }

tbox_css_stylesheet *tbox_ua_stylesheet_create(tbox_ua_style_config config) {
    /* One rule per original ruleset, in the original order. Keeping a
     * separate declaration for every property preserves cascade order. */
    const tbox_ua_rule rules[] = {
        UA_RULE_1("body", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_BLOCK), UA_QUAD(TBOX_UA_PROP_MARGIN, config.margin.body_px, config.margin.body_px, config.margin.body_px, config.margin.body_px), UA_LEN(TBOX_UA_PROP_FONT_SIZE, config.font.base_px, TBOX_UA_UNIT_PX)),
        UA_RULE_1("div", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_BLOCK)),
        UA_RULE_1("h1", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_BLOCK), UA_LEN(TBOX_UA_PROP_FONT_SIZE, config.font.heading_em[0], TBOX_UA_UNIT_EM), UA_KW(TBOX_UA_PROP_FONT_WEIGHT, TBOX_UA_KW_BOLD), UA_QUAD(TBOX_UA_PROP_MARGIN, config.margin.heading_px[0], 0, config.margin.heading_px[0], 0)),
        UA_RULE_1("h2", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_BLOCK), UA_LEN(TBOX_UA_PROP_FONT_SIZE, config.font.heading_em[1], TBOX_UA_UNIT_EM), UA_KW(TBOX_UA_PROP_FONT_WEIGHT, TBOX_UA_KW_BOLD), UA_QUAD(TBOX_UA_PROP_MARGIN, config.margin.heading_px[1], 0, config.margin.heading_px[1], 0)),
        UA_RULE_1("h3", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_BLOCK), UA_LEN(TBOX_UA_PROP_FONT_SIZE, config.font.heading_em[2], TBOX_UA_UNIT_EM), UA_KW(TBOX_UA_PROP_FONT_WEIGHT, TBOX_UA_KW_BOLD), UA_QUAD(TBOX_UA_PROP_MARGIN, config.margin.heading_px[2], 0, config.margin.heading_px[2], 0)),
        UA_RULE_1("h4", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_BLOCK), UA_LEN(TBOX_UA_PROP_FONT_SIZE, config.font.heading_em[3], TBOX_UA_UNIT_EM), UA_KW(TBOX_UA_PROP_FONT_WEIGHT, TBOX_UA_KW_BOLD), UA_QUAD(TBOX_UA_PROP_MARGIN, config.margin.heading_px[3], 0, config.margin.heading_px[3], 0)),
        UA_RULE_1("h5", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_BLOCK), UA_LEN(TBOX_UA_PROP_FONT_SIZE, config.font.heading_em[4], TBOX_UA_UNIT_EM), UA_KW(TBOX_UA_PROP_FONT_WEIGHT, TBOX_UA_KW_BOLD), UA_QUAD(TBOX_UA_PROP_MARGIN, config.margin.heading_px[4], 0, config.margin.heading_px[4], 0)),
        UA_RULE_1("h6", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_BLOCK), UA_LEN(TBOX_UA_PROP_FONT_SIZE, config.font.heading_em[5], TBOX_UA_UNIT_EM), UA_KW(TBOX_UA_PROP_FONT_WEIGHT, TBOX_UA_KW_BOLD), UA_QUAD(TBOX_UA_PROP_MARGIN, config.margin.heading_px[5], 0, config.margin.heading_px[5], 0)),
        UA_RULE_1("p", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_BLOCK), UA_QUAD(TBOX_UA_PROP_MARGIN, config.margin.paragraph_px, 0, config.margin.paragraph_px, 0)),
        UA_RULE_2("ul", "ol", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_BLOCK), UA_QUAD(TBOX_UA_PROP_MARGIN, config.margin.list_px, 0, config.margin.list_px, 0), UA_QUAD(TBOX_UA_PROP_PADDING, 0, 0, 0, config.list_padding_left_px)),
        UA_RULE_1("ul", UA_KW(TBOX_UA_PROP_LIST_STYLE_TYPE, TBOX_UA_KW_DISC)),
        UA_RULE_1("ol", UA_KW(TBOX_UA_PROP_LIST_STYLE_TYPE, TBOX_UA_KW_DECIMAL)),
        UA_RULE_1("li", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_BLOCK)),
        UA_RULE_1("button", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_INLINE_BLOCK), UA_BORDER(1, 128, 128, 128), UA_QUAD(TBOX_UA_PROP_PADDING, 4, 4, 4, 4)),
        UA_RULE_FOCUS("button", UA_BORDER(2, 0, 0, 255)),
        UA_RULE_1("input", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_INLINE_BLOCK), UA_LEN(TBOX_UA_PROP_WIDTH, 240, TBOX_UA_UNIT_PX), UA_BORDER(1, 128, 128, 128), UA_QUAD(TBOX_UA_PROP_PADDING, 4, 4, 4, 4)),
        UA_RULE_FOCUS("input", UA_BORDER(2, 0, 0, 255)),
        UA_RULE_INPUT_TYPE("checkbox", UA_LEN(TBOX_UA_PROP_WIDTH, 12, TBOX_UA_UNIT_PX), UA_LEN(TBOX_UA_PROP_HEIGHT, 12, TBOX_UA_UNIT_PX), UA_QUAD(TBOX_UA_PROP_PADDING, 0, 0, 0, 0), UA_COLOR(TBOX_UA_PROP_BACKGROUND_COLOR, 255, 255, 255)),
        UA_RULE_INPUT_TYPE("color", UA_LEN(TBOX_UA_PROP_WIDTH, 48, TBOX_UA_UNIT_PX), UA_LEN(TBOX_UA_PROP_HEIGHT, 24, TBOX_UA_UNIT_PX), UA_QUAD(TBOX_UA_PROP_PADDING, 2, 2, 2, 2), UA_COLOR(TBOX_UA_PROP_BACKGROUND_COLOR, 255, 255, 255)),
        UA_RULE_INPUT_TYPE("date", UA_LEN(TBOX_UA_PROP_WIDTH, 120, TBOX_UA_UNIT_PX), UA_COLOR(TBOX_UA_PROP_BACKGROUND_COLOR, 255, 255, 255)),
        UA_RULE_INPUT_TYPE("datetime-local", UA_LEN(TBOX_UA_PROP_WIDTH, 175, TBOX_UA_UNIT_PX), UA_COLOR(TBOX_UA_PROP_BACKGROUND_COLOR, 255, 255, 255)),
        UA_RULE_INPUT_TYPE("time", UA_LEN(TBOX_UA_PROP_WIDTH, 92, TBOX_UA_UNIT_PX), UA_COLOR(TBOX_UA_PROP_BACKGROUND_COLOR, 255, 255, 255)),
        UA_RULE_INPUT_TYPE("week", UA_LEN(TBOX_UA_PROP_WIDTH, 105, TBOX_UA_UNIT_PX), UA_COLOR(TBOX_UA_PROP_BACKGROUND_COLOR, 255, 255, 255)),
        UA_RULE_INPUT_TYPE("file", UA_LEN(TBOX_UA_PROP_WIDTH, 240, TBOX_UA_UNIT_PX), UA_LEN(TBOX_UA_PROP_HEIGHT, 24, TBOX_UA_UNIT_PX), UA_QUAD(TBOX_UA_PROP_PADDING, 2, 2, 2, 2), UA_COLOR(TBOX_UA_PROP_BACKGROUND_COLOR, 255, 255, 255)),
        UA_RULE_INPUT_TYPE("hidden", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_NONE)),
        UA_RULE_INPUT_TYPE("image", UA_LEN(TBOX_UA_PROP_WIDTH, 0, TBOX_UA_UNIT_AUTO), UA_QUAD(TBOX_UA_PROP_PADDING, 0, 0, 0, 0), UA_BORDER(0, 128, 128, 128)),
        UA_RULE_INPUT_TYPE("month", UA_LEN(TBOX_UA_PROP_WIDTH, 100, TBOX_UA_UNIT_PX), UA_COLOR(TBOX_UA_PROP_BACKGROUND_COLOR, 255, 255, 255)),
        UA_RULE_INPUT_TYPE("number", UA_LEN(TBOX_UA_PROP_WIDTH, 120, TBOX_UA_UNIT_PX), UA_COLOR(TBOX_UA_PROP_BACKGROUND_COLOR, 255, 255, 255)),
        UA_RULE_INPUT_TYPE("radio", UA_LEN(TBOX_UA_PROP_WIDTH, 12, TBOX_UA_UNIT_PX), UA_LEN(TBOX_UA_PROP_HEIGHT, 12, TBOX_UA_UNIT_PX), UA_QUAD(TBOX_UA_PROP_PADDING, 0, 0, 0, 0), UA_COLOR(TBOX_UA_PROP_BACKGROUND_COLOR, 255, 255, 255), UA_LEN(TBOX_UA_PROP_BORDER_RADIUS, 7, TBOX_UA_UNIT_PX)),
        UA_RULE_INPUT_TYPE("range", UA_LEN(TBOX_UA_PROP_WIDTH, 160, TBOX_UA_UNIT_PX), UA_LEN(TBOX_UA_PROP_HEIGHT, 20, TBOX_UA_UNIT_PX), UA_QUAD(TBOX_UA_PROP_PADDING, 0, 0, 0, 0), UA_BORDER(0, 128, 128, 128)),
        UA_RULE_INPUT_TYPE("reset", UA_COLOR(TBOX_UA_PROP_BACKGROUND_COLOR, 255, 255, 255)),
        UA_RULE_INPUT_TYPE("search", UA_COLOR(TBOX_UA_PROP_BACKGROUND_COLOR, 255, 255, 255)),
        UA_RULE_INPUT_TYPE("submit", UA_COLOR(TBOX_UA_PROP_BACKGROUND_COLOR, 255, 255, 255)),
        UA_RULE_1("select", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_INLINE_BLOCK), UA_LEN(TBOX_UA_PROP_WIDTH, 240, TBOX_UA_UNIT_PX), UA_BORDER(1, 128, 128, 128), UA_QUAD(TBOX_UA_PROP_PADDING, 4, 4, 4, 4), UA_COLOR(TBOX_UA_PROP_BACKGROUND_COLOR, 255, 255, 255)),
        UA_RULE_FOCUS("select", UA_BORDER(2, 0, 0, 255)),
        UA_RULE_1("textarea", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_INLINE_BLOCK), UA_BORDER(1, 128, 128, 128), UA_QUAD(TBOX_UA_PROP_PADDING, 4, 4, 4, 4), UA_COLOR(TBOX_UA_PROP_BACKGROUND_COLOR, 255, 255, 255)),
        UA_RULE_FOCUS("textarea", UA_BORDER(2, 0, 0, 255)),
        UA_RULE_1("hr", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_BLOCK), UA_LEN(TBOX_UA_PROP_HEIGHT, config.hr_height_px, TBOX_UA_UNIT_PX), UA_COLOR(TBOX_UA_PROP_BACKGROUND_COLOR, 128, 128, 128), UA_QUAD(TBOX_UA_PROP_MARGIN, config.margin.hr_px, 0, config.margin.hr_px, 0)),
        UA_RULE_1("pre", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_BLOCK), UA_KW(TBOX_UA_PROP_FONT_FAMILY, TBOX_UA_KW_MONOSPACE), UA_KW(TBOX_UA_PROP_WHITE_SPACE, TBOX_UA_KW_PRE)),
        UA_RULE_2("b", "strong", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_INLINE), UA_KW(TBOX_UA_PROP_FONT_WEIGHT, TBOX_UA_KW_BOLD)),
        UA_RULE_2("i", "em", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_INLINE), UA_KW(TBOX_UA_PROP_FONT_STYLE, TBOX_UA_KW_ITALIC)),
        UA_RULE_1("span", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_INLINE)),
        UA_RULE_1("a", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_INLINE), UA_COLOR(TBOX_UA_PROP_COLOR, 0, 0, 255), UA_KW(TBOX_UA_PROP_TEXT_DECORATION, TBOX_UA_KW_UNDERLINE)),
        UA_RULE_1("img", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_INLINE)),
        UA_RULE_1("small", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_INLINE), UA_LEN(TBOX_UA_PROP_FONT_SIZE, 80, TBOX_UA_UNIT_PERCENT)),
        UA_RULE_1("mark", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_INLINE), UA_COLOR(TBOX_UA_PROP_BACKGROUND_COLOR, 255, 255, 0)),
        UA_RULE_1("del", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_INLINE), UA_KW(TBOX_UA_PROP_TEXT_DECORATION, TBOX_UA_KW_LINE_THROUGH)),
        UA_RULE_1("ins", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_INLINE), UA_KW(TBOX_UA_PROP_TEXT_DECORATION, TBOX_UA_KW_UNDERLINE)),
        UA_RULE_1("sub", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_INLINE), UA_LEN(TBOX_UA_PROP_FONT_SIZE, 75, TBOX_UA_UNIT_PERCENT), UA_KW(TBOX_UA_PROP_VERTICAL_ALIGN, TBOX_UA_KW_SUB)),
        UA_RULE_1("sup", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_INLINE), UA_LEN(TBOX_UA_PROP_FONT_SIZE, 75, TBOX_UA_UNIT_PERCENT), UA_KW(TBOX_UA_PROP_VERTICAL_ALIGN, TBOX_UA_KW_SUPER)),
        UA_RULE_6("table", "tr", "thead", "tbody", "tfoot", "caption", UA_KW(TBOX_UA_PROP_DISPLAY, TBOX_UA_KW_BLOCK)),
        UA_RULE_1("caption", UA_KW(TBOX_UA_PROP_TEXT_ALIGN, TBOX_UA_KW_CENTER)),
        UA_RULE_1("th", UA_KW(TBOX_UA_PROP_FONT_WEIGHT, TBOX_UA_KW_BOLD), UA_KW(TBOX_UA_PROP_TEXT_ALIGN, TBOX_UA_KW_CENTER)),
        UA_RULE_2("td", "th", UA_QUAD(TBOX_UA_PROP_PADDING, 4, 4, 4, 4)),
    };

    return tbox_ua_build_stylesheet(rules, sizeof(rules) / sizeof(rules[0]));
}

#undef UA_KW
#undef UA_LEN
#undef UA_QUAD
#undef UA_COLOR
#undef UA_BORDER
#undef UA_DECLARATIONS
#undef UA_DECLARATION_COUNT
#undef UA_RULE_1
#undef UA_RULE_2
#undef UA_RULE_6
#undef UA_RULE_FOCUS
#undef UA_RULE_INPUT_TYPE
